/* @lc app=leetcode id=1797 lang=kotlin */
class AuthenticationManager(val timeToLive: Int, val map: java.util.HashMap<String, Int> = java.util.HashMap()) { fun generate(tokenId: String, currentTime: Int) { map[tokenId] = currentTime + timeToLive } fun renew(tokenId: String, currentTime: Int) { if ((map[tokenId] ?: 0) > currentTime) map[tokenId] = currentTime + timeToLive } fun countUnexpiredTokens(currentTime: Int) = map.values.count { it > currentTime } }